const input = $input.first().json || {};
const executionUrl = String(input.executionUrl || "").slice(0, 1000);
const workflowIdFromUrl = (executionUrl.match(/\/workflow\/([^/]+)(?:\/executions\/|$)/) || [])[1] || "";
return [{
  json: {
    alert_type: "error",
    severity_hint: "warning",
    source_workflow_id: String(input.workflowId || workflowIdFromUrl).slice(0, 200),
    source_workflow_name: String(input.workflowName || "Unknown Workflow").slice(0, 300),
    subject: String(input.emailSubject || ("N8N Fehler: " + (input.workflowName || "Unknown Workflow"))).slice(0, 500),
    metadata: {
      execution_id: String(input.executionId || "").slice(0, 200),
      execution_url: executionUrl,
      error_message: String(input.errorMessage || "Unknown error").slice(0, 2000),
      last_node: String(input.lastNode || "unknown").slice(0, 300),
    },
  },
}];

router:
function text(value, maxLength) {
  return String(value ?? "").trim().slice(0, maxLength);
}

function redact(value) {
  return text(value, 2000)
    .replace(/bearer\s+[a-z0-9._~+\/-]+=*/gi, "[redacted-token]")
    .replace(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/gi, "[redacted-email]")
    .replace(/https?:\/\/[^\s"'<>]+/gi, "[redacted-url]")
    .replace(/\+?[0-9][0-9() ./-]{7,}[0-9]/g, "[redacted-phone]")
    .replace(/\b[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\b/gi, "[redacted-uuid]")
    .replace(/\b[0-9a-f]{24,}\b/gi, "[redacted-token]")
    .replace(/\b\d{6,}\b/g, "[redacted-number]")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizeForFingerprint(value) {
  return redact(value)
    .toLowerCase()
    .replace(/\bexecution(?: id)?[: #=-]*\d+\b/gi, "execution [id]")
    .replace(/\b(?:attempt|retry)[: #=-]*\d+\b/gi, "attempt [n]")
    .replace(/\b\d+(?:\.\d+)?\s*(?:ms|milliseconds?|seconds?|secs?|s)\b/gi, "[duration]")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 1000);
}

function fnv1a(value, seed) {
  let hash = seed >>> 0;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return ("00000000" + (hash >>> 0).toString(16)).slice(-8);
}

function classifyRootCause(message) {
  if (/invalid_grant|refresh token|expired|revoked|unauthori[sz]ed|oauth|authentication/.test(message)) return "credential_or_auth";
  if (/forbidden|permission[_ ]denied|access denied|insufficient privilege/.test(message)) return "permission";
  if (/429|rate limit|quota exceeded|too many requests/.test(message)) return "rate_limit";
  if (/timeout|timed out|etimedout|econnrefused|enotfound|socket hang up/.test(message)) return "dependency_unavailable";
  if (/cannot read|undefined|null|typeerror|referenceerror|schema|validation/.test(message)) return "data_shape_or_validation";
  if (/5\d\d|bad gateway|service unavailable|upstream/.test(message)) return "external_service";
  return "unclassified_workflow_error";
}

const input = $input.first().json || {};
const metadata = input.metadata && typeof input.metadata === "object" ? input.metadata : {};
const workflowId = text(input.source_workflow_id || input.workflowId || input.workflow?.id, 200);
const workflowName = text(input.source_workflow_name || input.workflowName || input.workflow?.name || "Unknown Workflow", 300);
const executionId = text(metadata.execution_id || input.executionId || input.execution?.id, 200);
const executionUrl = text(metadata.execution_url || input.executionUrl || input.execution?.url, 1000);
const lastNode = text(metadata.last_node || input.lastNode || input.execution?.lastNodeExecuted || "unknown", 300);
const rawError = text(metadata.error_message || input.errorMessage || input.execution?.error?.message || input.subject || "unknown error", 2000);

if (!workflowId || !workflowName) {
  throw new Error("internal_alert_router_invalid_source_identity");
}

const normalizedError = normalizeForFingerprint(rawError) || "unknown error";
const rootCause = classifyRootCause(normalizedError);
const signatureSource = [workflowId.toLowerCase(), lastNode.toLowerCase(), rootCause, normalizedError].join("|");
const signature = fnv1a(signatureSource, 2166136261) + fnv1a(signatureSource, 3339675911);
const fingerprint = ("n8n-alert:" + workflowId.toLowerCase() + ":" + signature).slice(0, 500);
const requestedSeverity = text(input.severity_hint || "warning", 20).toLowerCase();
const severity = ["info", "warning", "critical"].includes(requestedSeverity) ? requestedSeverity : "warning";
const alertType = text(input.alert_type || "error", 80).toLowerCase().replace(/[^a-z0-9_-]+/g, "_") || "error";
const redactedPreview = redact(rawError).slice(0, 500);

return [{
  json: {
    router_mode: "shadow",
    router_version: "internal-alert-router-v1",
    fingerprint,
    signature,
    rpc_payload: {
      p_fingerprint: fingerprint,
      p_incident_type: "n8n_" + alertType,
      p_severity: severity,
      p_title: ("n8n: " + workflowName + " failed").slice(0, 500),
      p_detail: [
        "Workflow: " + workflowName,
        "Node: " + lastNode,
        "Cause: " + rootCause,
        "Redacted error: " + redactedPreview,
        "Signature: " + signature,
      ].join("\n").slice(0, 5000),
      p_root_cause_code: rootCause,
      p_workflow_execution_id: executionId || null,
      p_source_key: "n8n",
      p_source_ref: executionUrl || null,
      p_evidence_refs: executionId ? [{ type: "n8n_execution", id: executionId }] : [],
      p_owner_team: "operations",
      p_metadata: {
        router_mode: "shadow",
        router_version: "internal-alert-router-v1",
        source_workflow_id: workflowId,
        source_workflow_name: workflowName,
        last_node: lastNode,
        error_signature: signature,
        error_preview_redacted: redactedPreview,
      },
      p_actor: "n8n-internal-alert-router",
      p_reopen: true,
    },
  },
}];

gate:
// Internal notification gate: new problems remain visible, repetitions are bundled.
// No customer recipient, business operation or payment state is changed here.
const text = value => String(value ?? '').trim();
const escapeHtml = value => text(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const now = Date.now();
const day = 24 * 60 * 60 * 1000;
const state = $getWorkflowStaticData('global');
const gate = state.internalErrorMailGateV2 ||= { issues: {}, invalidCount: 0 };
const allowed = new Set(['info@neontrip.de', 'support@neontrip.de', 'rh@neontrip.de']);
const outputs = [];
function stable(value) {
  return text(value)
    .replace(/https?:\/\/[^\s<>"']+/g, '[link]')
    .replace(/\b\d{4}-\d{2}-\d{2}T[\d:.]+Z\b/g, '[time]')
    .replace(/\b\d{1,2}\.\d{1,2}\.\d{4}(?:,?\s+\d{1,2}:\d{2}(?::\d{2})?)?/g, '[date]')
    .replace(/\b(?:execution|request)[-_ ]?id\s*[:=]\s*[^\s<,;]+/gi, '[execution]')
    .replace(/\s+/g, ' ').trim();
}
function hash(value) {
  let a = 2166136261, b = 5381;
  for (let i = 0; i < value.length; i++) { a = Math.imul(a ^ value.charCodeAt(i), 16777619); b = Math.imul(b, 33) ^ value.charCodeAt(i); }
  return (a >>> 0).toString(16) + ':' + (b >>> 0).toString(16);
}
for (const [key, issue] of Object.entries(gate.issues)) {
  if (!issue || now - Number(issue.lastSeenAt || 0) > 7 * day) delete gate.issues[key];
}
for (const item of $input.all()) {
  const input = item?.json || {};
  if (input.sendAlert === false || input.dryRun === true) continue;
  const subject = text(input.subject || input.emailSubject).replace(/[\r\n]+/g, ' ').slice(0, 300);
  const body = text(input.body_html || input.emailBody).slice(0, 50000);
  // Never turn malformed/empty notification inputs into another notification loop.
  if (!subject || !body || !body.replace(/<[^>]*>/g, '').replace(/&nbsp;/g, '').trim()) {
    gate.invalidCount++; gate.lastInvalidAt = now; continue;
  }
  const recipientRaw = text(input.emailRecipient || input.recipient || input.toRecipients || 'info@neontrip.de');
  const recipients = [...new Set(recipientRaw.split(/[;,]/).map(v => v.trim().toLowerCase()).filter(Boolean))].sort();
  if (!recipients.length || recipients.some(v => !allowed.has(v))) throw new Error('internal_error_mail_recipient_not_allowed');
  const metadata = input.metadata || {};
  const workflowName = text(input.source_workflow_name || input.workflowName);
  const errorMessage = text(metadata.error_message || input.errorMessage);
  const description = text(metadata.error_description || input.errorDescription);
  const node = text(metadata.failed_node || input.lastNode || input.failedNode);
  // Prefer structured error data. Different error descriptions and severity escalations
  // must remain separate even when the upstream fingerprint was coarsely normalized.
  const bodyForKey = body
    .replace(/<tr\b[^>]*>[\s\S]*?<\/tr>/gi, row => /Execution ID|Execution Link|Zeit<|Unterdrückt seit letzter Meldung/i.test(row) ? '' : row)
    .replace(/<hr>[\s\S]*?Gebündelt:[\s\S]*$/i, '')
    .replace(/<[^>]*>/g, ' ');
  const detail = errorMessage ? [node, stable(errorMessage), stable(description)].join('|') : stable(bodyForKey);
  const key = hash([recipients.join(','), subject, workflowName, detail, text(input.severity_hint || input.severity)].join('|'));
  let issue = gate.issues[key];
  if (!issue) issue = { lastApprovedAt: 0, lastSeenAt: now, suppressed: 0 };
  issue.lastSeenAt = now;
  if (issue.lastApprovedAt && now - issue.lastApprovedAt < day) {
    issue.suppressed++; gate.issues[key] = issue; continue;
  }
  const suppressed = Number(issue.suppressed || 0);
  const isTest = /(?:^|[\s|\[—-])(?:TEMP|TEST|PREFLIGHT|SMOKE|BACKUP)(?:$|[\s|\]—-])/i.test(workflowName || subject);
  const summary = '<hr><p style="font-family:Arial,sans-serif;color:#666;font-size:12px">'
    + (suppressed ? '<strong>Gebündelt:</strong> ' + suppressed + ' weitere identische Meldung(en) seit der letzten Freigabe. ' : '')
    + 'Identische Meldungen werden für 24 Stunden gebündelt. Neue Fehler, betroffene Vorgänge oder eine höhere Einstufung werden separat gemeldet. Details bleiben in den n8n-Ausführungen erhalten.</p>';
  const legacy = state.internalErrorMailGate;
  const legacySummary = legacy?.suppressed > 0
    ? '<p><strong>Vorherige Sammelmeldungen:</strong> ' + Number(legacy.suppressed) + '</p><ul>'
      + (legacy.suppressedSubjects || []).map(s => '<li>' + escapeHtml(s) + '</li>').join('') + '</ul>' : '';
  if (legacy?.suppressed > 0) { legacy.suppressed = 0; legacy.suppressedSubjects = []; }
  issue.lastApprovedAt = now; issue.suppressed = 0; gate.issues[key] = issue;
  const finalSubject = isTest && !/^\[TEST\]/.test(subject) ? '[TEST] ' + subject : subject;
  const normalizedBody = body + summary + legacySummary;
  outputs.push({ json: { ...input, gateApproved: true, emailRecipient: recipients.join(','), emailSubject: finalSubject,
    emailBody: normalizedBody, subject: finalSubject, body_html: normalizedBody,
    gateSuppressedSinceLastSend: suppressed, gateDedupeWindowMinutes: 1440, gateVersion: 2 } });
}
// Bound static state; eviction may cause an extra notification, never suppress a new one.
const keys = Object.keys(gate.issues);
if (keys.length > 2000) {
  keys.sort((a,b) => gate.issues[a].lastSeenAt - gate.issues[b].lastSeenAt);
  for (const key of keys.slice(0, keys.length - 2000)) delete gate.issues[key];
}
return outputs;
